function aiCandidateCard(aiCandidate,labels){const card=document.createElement('article');card.className='ai-candidate-card';const heading=document.createElement('div');heading.className='ai-candidate-heading';heading.append(textElement('strong','ai-candidate-name',aiCandidate.name));const score=Math.round(Number(aiCandidate.match_score||0));if(score>0)heading.append(textElement('span','ai-intent-confidence-score',`${score}%`));card.append(heading);if(aiCandidate.brand)card.append(aiIntentRow(labels.brand,textElement('span','ai-intent-value',aiCandidate.brand)));if(aiCandidate.reason)card.append(aiIntentRow(labels.reason,textElement('span','ai-intent-value',aiCandidate.reason)));const features=bulletList('ai-intent-features',aiCandidate.matched_features);if(features)card.append(aiIntentRow(labels.features,features));const links=marketplaceLinks(aiCandidate.marketplace_search_links,true);if(links)card.append(links);return card;}
function aiCandidateCards(candidates,language){const list=(Array.isArray(candidates)?candidates:[]).filter(aiCandidate=>aiCandidate?.name);if(!list.length)return null;const labels=aiIntentLabels[language]||aiIntentLabels.JA;const wrap=document.createElement('div');wrap.className='ai-candidate-list';wrap.append(textElement('strong','ai-candidate-list-title',labels.candidates));list.forEach(aiCandidate=>wrap.append(aiCandidateCard(aiCandidate,labels)));return wrap;}
function keywordTags(value){const seen=new Set();const tags=[];for(const part of String(value||'').split(/[\/\n]+/)){for(const token of part.trim().split(/\s+/)){const clean=token.trim();if(!clean)continue;const key=clean.toLocaleLowerCase();if(seen.has(key))continue;seen.add(key);tags.push(clean);if(tags.length>=12)return tags;}}return tags;}
function keywordTagBlock(value,actions,label){const tags=keywordTags(value);if(!tags.length)return null;const wrap=document.createElement('div');wrap.className='keyword-tag-block';if(label)wrap.append(textElement('span','ai-intent-label keyword-tag-label',label));const list=document.createElement('div');list.className='keyword-tag-list';tags.forEach(tag=>list.append(textElement('span','keyword-tag',tag)));const copyButton=document.createElement('button');copyButton.type='button';copyButton.className='copy-keywords copy-all-keywords';copyButton.textContent=actions.copyKeywords;copyButton.addEventListener('click',()=>copySearchKeywords(value,copyButton,actions));wrap.append(list,copyButton);return wrap;}
// AI related-keyword suggestions (Phase C item 11, 2026-08-07). The
// keywordTagBlock above only ever echoed the user's own words back as
// read-only chips, so on a search that returned products there was no way
// to narrow down without retyping. These chips are tappable and append to
// the existing condition using the same " / " convention runKnowledgeSearch
// already treats as "same search root, attempt 2".
//
// Every suggestion is real data, never an invented term:
//   1. the AI intent analysis (search_keywords / candidate brands+names /
//      features) when it ran - index.mjs only calls discoverProductsWithAi
//      when the search returned zero candidates, so this source is the
//      zero-result path;
//   2. the matched terms and product titles of the products HOSHILU
//      actually found, frequency-ranked, on the has-results path.
// Terms already in the query are dropped: re-adding them is a no-op.
const relatedKeywordCopy={
  JA:{ai:'AI連想キーワード（タップで検索条件に追加）',result:'検索結果からの関連キーワード（タップで検索条件に追加）'},
  EN:{ai:'AI related keywords (tap to add to your search)',result:'Related keywords from these results (tap to add to your search)'},
  ZH:{ai:'AI联想关键词（点击加入搜索条件）',result:'来自搜索结果的相关关键词（点击加入搜索条件）'},
  KO:{ai:'AI 연상 키워드 (탭하여 검색 조건에 추가)',result:'검색 결과의 관련 키워드 (탭하여 검색 조건에 추가)'}
};
// Marketplace listing titles are padded with promo boilerplate ("送料無料",
// "正規品", ...). Suggesting those as refinements would narrow the search by
// seller marketing rather than by product attributes, so they are dropped.
const relatedKeywordStopWords=new Set(['送料無料','送料込み','送料込','正規品','新品','中古','未使用','即日発送','あす楽','ポイント','ポイント10倍','セール','sale','限定','数量限定','期間限定','クーポン','まとめ買い','公式','公式ストア','日本製','国内発送','ラッピング','ギフト','プレゼント','人気','おすすめ','高品質','最安値','激安','翌日配送','在庫あり','set','セット','新作','対応','用','的','and','the','for','with','a','of']);
function splitKeywordTokens(value){return String(value||'').split(/[\s/／・|｜,、，.。;；:：!！?？~〜+＋*＊"'“”‘’()（）\[\]【】「」『』<>＜＞{}]+/u).map(token=>token.trim()).filter(Boolean);}
function queryTokenSet(query){const set=new Set();splitKeywordTokens(query).forEach(token=>set.add(token.toLocaleLowerCase()));return set;}
function relatedKeywordSuggestions(result,query){
  const used=queryTokenSet(query);
  const seen=new Set();
  const aiTerms=[];
  const resultTerms=new Map();
  const clean=value=>{
    const text=String(value||'').trim().replace(/\s+/g,' ');
    if(text.length<2||text.length>28)return'';
    const key=text.toLocaleLowerCase();
    if(used.has(key)||seen.has(key)||relatedKeywordStopWords.has(key))return'';
    if(!/[\p{L}\p{N}]/u.test(text)||/^[\p{N}\p{P}\s]+$/u.test(text))return'';
    return text;
  };
  const pushAi=value=>{const text=clean(value);if(!text)return;seen.add(text.toLocaleLowerCase());aiTerms.push(text);};
  const countResult=value=>{const text=clean(value);if(!text)return;const key=text.toLocaleLowerCase();resultTerms.set(key,{text,count:(resultTerms.get(key)?.count||0)+1});};
  const analysis=result?.ai_discovery?.analysis||null;
  (analysis?.search_keywords||[]).forEach(pushAi);
  (analysis?.product_candidates||[]).forEach(candidate=>{pushAi(candidate?.brand);pushAi(candidate?.name);});
  (analysis?.features||[]).forEach(pushAi);
  (result?.candidates||[]).forEach(candidate=>{
    (candidate?.evidence?.matched_terms||[]).forEach(countResult);
    splitKeywordTokens(candidate?.display_name||candidate?.product_name||'').forEach(countResult);
  });
  const ranked=[...resultTerms.values()].sort((a,b)=>b.count-a.count).map(entry=>entry.text);
  return{aiSourced:aiTerms.length>0,terms:[...aiTerms,...ranked].slice(0,12)};
}
function applyRelatedKeyword(term){
  // " / " is the refinement separator runKnowledgeSearch() already parses to
  // detect "same root, narrowed" - reusing it keeps searchAttempt correct.
  const current=String(elements.query.value||'').trim();
  elements.query.value=current?`${current} / ${term}`:term;
  elements.clear?.classList.remove('hidden');
  runKnowledgeSearch();
}
function relatedKeywordCard(result){
  const language=elements.language.value;
  const query=String(elements.query.value||'');
  const{aiSourced,terms}=relatedKeywordSuggestions(result,query);
  if(terms.length<5)return null;
  const copy=relatedKeywordCopy[language]||relatedKeywordCopy.JA;
  const card=document.createElement('article');
  card.className='refinement-card related-keyword-card';
  const wrap=document.createElement('div');
  wrap.className='keyword-tag-block related-keyword-block';
  wrap.append(textElement('span','ai-intent-label keyword-tag-label',aiSourced?copy.ai:copy.result));
  const list=document.createElement('div');
  list.className='keyword-tag-list';
  terms.forEach(term=>{
    const chip=document.createElement('button');
    chip.type='button';
    chip.className='keyword-tag related-keyword-tag';
    chip.textContent=term;
    chip.addEventListener('click',()=>applyRelatedKeyword(term));
    list.append(chip);
  });
  wrap.append(list);
  card.append(wrap);
  return card;
}
// Condition search (Phase C item 11, 2026-08-07). This is the second entry
// point into the SAME search condition the AI free-text box drives, not a
// separate search mode: picking chips appends their labels to the current
// query with " / " - exactly what applyRefinementChips() does server-side and
// what runKnowledgeSearch() already parses as "same root, narrowed". So one
// query string remains the single condition model, reachable either by
// describing the product in words or by picking conditions.
//
// The groups, labels and per-language copy all come from the server
// (refinement_chips, built by search-refinement-policy.mjs) so this file
// never holds a second copy of that dictionary. One value per dimension,
// matching applyRefinementChips()'s own one-chip-per-dimension rule.
const conditionSearchCopy={
  JA:{title:'条件で絞り込む',body:'各項目から1つずつ選べます。選んだ条件は今の検索にそのまま追加されます。',submit:'この条件で探す'},
  EN:{title:'Narrow by condition',body:'Pick up to one from each row. Your choices are added to the current search.',submit:'Search with these conditions'},
  ZH:{title:'按条件筛选',body:'每项最多选择一个，所选条件将直接加入当前搜索。',submit:'用这些条件搜索'},
  KO:{title:'조건으로 좁히기',body:'각 항목에서 하나씩 선택할 수 있습니다. 선택한 조건은 현재 검색에 추가됩니다.',submit:'이 조건으로 찾기'}
};
function conditionSearchCard(result){
  const groups=(Array.isArray(result?.refinement_chips)?result.refinement_chips:[]).filter(group=>group?.label&&group?.values?.length);
  if(!groups.length)return null;
  const copy=conditionSearchCopy[elements.language.value]||conditionSearchCopy.JA;
  const selected=new Map();
  const card=document.createElement('article');
  card.className='refinement-card condition-search-card';
  card.append(textElement('strong','condition-search-title',copy.title),textElement('p','condition-search-body',copy.body));
  const submit=document.createElement('button');
  submit.type='button';
  submit.className='primary condition-search-submit';
  submit.textContent=copy.submit;
  submit.disabled=true;
  groups.forEach(group=>{
    const row=document.createElement('div');
    row.className='condition-group';
    row.append(textElement('span','condition-group-label',group.label));
    const list=document.createElement('div');
    list.className='condition-value-list';
    group.values.filter(item=>item?.label).forEach(item=>{
      const chip=document.createElement('button');
      chip.type='button';
      chip.className='keyword-tag condition-chip';
      chip.textContent=item.label;
      chip.setAttribute('aria-pressed','false');
      chip.addEventListener('click',()=>{
        const active=selected.get(group.dimension)===item.label;
        // one value per dimension: clear the row, then set unless re-tapped
        [...list.children].forEach(node=>{node.classList.remove('selected');node.setAttribute('aria-pressed','false');});
        if(active)selected.delete(group.dimension);
        else{selected.set(group.dimension,item.label);chip.classList.add('selected');chip.setAttribute('aria-pressed','true');}
        submit.disabled=selected.size===0;
      });
      list.append(chip);
    });
    row.append(list);
    card.append(row);
  });
  submit.addEventListener('click',()=>{
    if(!selected.size)return;
    const base=String(elements.query.value||'').trim();
    elements.query.value=[base,...selected.values()].filter(Boolean).join(' / ');
    elements.clear?.classList.remove('hidden');
    runKnowledgeSearch();
  });
  card.append(submit);
  return card;
}
function marketplaceFallbackGroup(label,linksNode){if(!linksNode)return null;const group=document.createElement('div');group.className='marketplace-fallback-group';group.append(textElement('p','marketplace-fallback-group-label',label),linksNode);return group;}
function marketplaceFallbackCard(result){if(!result?.marketplace_search_links?.length&&!result?.amazon_search_url)return null;const labels={JA:['10モールとSNSを横断して探す','Amazon・楽天市場・Yahoo!ショッピング・Qoo10・SHEIN・ZOZOTOWN・SHOPLIST・MUSINSA・BUYMA・SNKRDUNKと、Instagram・X・TikTok・YouTubeで探せます。','モールで探す','SNSで探す'],EN:['Search ten marketplaces and social platforms','Search ten marketplaces plus Instagram, X, TikTok, and YouTube with the same terms.','Marketplaces','Social search'],ZH:['跨十个商城和社交平台查找','可在十个商城以及 Instagram、X、TikTok 和 YouTube 继续搜索。','商城','社交平台'],KO:['10개 쇼핑몰과 SNS에서 함께 찾기','10개 쇼핑몰과 Instagram, X, TikTok, YouTube에서 같은 조건으로 찾을 수 있습니다.','쇼핑몰','SNS']};const [label,body,mallLabel,socialLabel]=labels[elements.language.value]||labels.JA;const actions=actionCopy[elements.language.value]||actionCopy.JA;const language=elements.language.value;const card=document.createElement('article');card.className='refinement-card marketplace-fallback';card.id='marketplaceFallback';const intro=document.createElement('div');intro.className='marketplace-fallback-intro';intro.append(textElement('strong','',label),textElement('p','',body));const analysis=result?.ai_discovery?.analysis||null;const intentBlock=aiIntentSummaryBlock(analysis,language);if(intentBlock)intro.append(intentBlock);const candidateCards=aiCandidateCards(analysis?.product_candidates,language);if(candidateCards)intro.append(candidateCards);const keywords=String(elements.query.value||result?.search_keywords||result?.amazon_search_keywords||'');const tagSource=analysis?.search_keywords?.length?analysis.search_keywords.join(' '):keywords;const tagBlock=keywordTagBlock(tagSource,actions,(aiIntentLabels[language]||aiIntentLabels.JA).keywords);if(tagBlock)intro.append(tagBlock);card.append(intro);const legacy=result.amazon_search_url?[{marketplace:'AMAZON_JP',label:'Amazonで探す',url:result.amazon_search_url}]:[];const mallGroup=marketplaceFallbackGroup(mallLabel,marketplaceLinks(result.marketplace_search_links?.length?result.marketplace_search_links:legacy));if(mallGroup)card.append(mallGroup);const socialLinks=marketplaceLinks(socialDiscoverySearchLinks(keywords));if(socialLinks){socialLinks.classList.add('social-search-links');const socialGroup=marketplaceFallbackGroup(socialLabel,socialLinks);if(socialGroup)card.append(socialGroup);}return card;}
function aiDiscoveryCard(result){const items=(result?.ai_discovery?.candidates||[]).filter(item=>item?.url&&item?.image).slice(0,3);if(!items.length)return null;const labels={JA:['AIが見つけた可能性のある商品','10モールで確認できなかったため、公開Webから近い候補を探しました。未確認候補のため、商品ページで内容を確認してください。','候補ページを見る'],EN:['Possible products found by AI','The ten marketplaces had no confirmed match, so AI searched the public web. These are unconfirmed leads; verify the product page.','View candidate page'],ZH:['AI找到的可能商品','十个商城均无确认结果，因此AI搜索了公开网页。这些是未确认候选，请在商品页核实。','查看候选页面'],KO:['AI가 찾은 가능성 있는 상품','10개 쇼핑몰에서 확인되지 않아 공개 웹에서 비슷한 후보를 찾았습니다. 미확인 후보이므로 상품 페이지에서 확인하세요.','후보 페이지 보기']}[elements.language.value]||null;const card=document.createElement('article');card.className='ai-discovery-card';card.append(textElement('span','ai-discovery-badge','AI DISCOVERY'),textElement('h3','',labels[0]),textElement('p','ai-discovery-notice',labels[1]));const list=document.createElement('div');list.className='ai-discovery-list';items.forEach(item=>{const link=document.createElement('a');link.className='ai-discovery-item';link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';const image=document.createElement('img');image.src=item.image;image.alt='';image.loading='lazy';image.referrerPolicy='no-referrer';link.append(image,textElement('strong','',item.title),textElement('small','',item.source||''),textElement('span','',labels[2]));list.append(link);});card.append(list);return card;}function renderResults(result,requestId){const t=selectedCopy();elements.results.classList.remove('hidden');elements.message.textContent=result.message||'';const candidates=(result.candidates||[]).slice(0,30);console.info('SEARCH_TRACE_CLIENT',{requestId,stage:'11_ui_render',ui_render_count:candidates.length});const cards=candidates.map((candidate,index)=>{const card=document.createElement('article');card.className='product-card';const safeRank=Math.max(1,Number(candidate.rank)||index+1);card.append(textElement('span','rank',`NO. ${safeRank}`));if(candidate.image){const image=document.createElement('img');image.className='product-image';image.src=candidate.image;image.alt='';image.loading='lazy';image.referrerPolicy='no-referrer';card.append(image);}card.append(textElement('h3','',candidate.display_name||candidate.product_name||candidate.asin));if(candidate.description)card.append(textElement('p','',candidate.description));const terms=candidate.evidence?.matched_terms||[];if(terms.length)card.append(textElement('div','evidence',`${window.HoshiluI18n?.t('search.evidence',elements.language.value)||'一致した手がかり：'}${terms.slice(0,4).join(' / ')}`));const options=renderOfferOptions(candidate,t,elements.language.value,result);if(options)card.append(options);else card.append(allMarketplacesButton());const watch=createWatchOptions(t);card.append(watch.bell,watch.dialog);return card;});if(cards.length){const carousel=document.createElement('div');carousel.className='result-carousel';const track=document.createElement('div');track.className='result-track';track.append(...cards);carousel.append(track);if(cards.length>3){const previous=document.createElement('button');previous.type='button';previous.className='carousel-button previous';previous.setAttribute('aria-label','前の商品を見る');previous.textContent='‹';const next=document.createElement('button');next.type='button';next.className='carousel-button next';next.setAttribute('aria-label','次の商品を見る');next.textContent='›';const move=direction=>track.scrollBy({left:direction*track.clientWidth,behavior:'smooth'});previous.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));carousel.append(previous,next);}const resultCards=[];const clarification=clarificationCard(result);if(clarification)resultCards.push(clarification);resultCards.push(carousel);const relatedKeywords=relatedKeywordCard(result);if(relatedKeywords)resultCards.push(relatedKeywords);const conditionSearch=conditionSearchCard(result);if(conditionSearch)resultCards.push(conditionSearch);resultCards.push(refinementCard());const marketplaceFallback=marketplaceFallbackCard(result);if(marketplaceFallback)resultCards.push(marketplaceFallback);elements.cards.replaceChildren(...resultCards);}else{const emptyCards=[];const clarification=clarificationCard(result);if(clarification)emptyCards.push(clarification);const empty=document.createElement('article');empty.className='empty-result';empty.append(textElement('p','',elements.query.value));const wish=document.createElement('button');wish.type='button';wish.className='wish-button';wish.textContent=t.wish;wish.addEventListener('click',()=>{saveWish(elements.query.value);wish.textContent=t.wishSaved;wish.disabled=true;});empty.append(wish);emptyCards.push(empty);const emptyRelatedKeywords=relatedKeywordCard(result);if(emptyRelatedKeywords)emptyCards.push(emptyRelatedKeywords);const emptyConditionSearch=conditionSearchCard(result);if(emptyConditionSearch)emptyCards.push(emptyConditionSearch);const aiCard=aiDiscoveryCard(result);if(aiCard)emptyCards.push(aiCard);const marketplaceFallback=marketplaceFallbackCard(result);if(marketplaceFallback)emptyCards.push(marketplaceFallback);elements.cards.replaceChildren(...emptyCards);}elements.results.scrollIntoView({behavior:'smooth',block:'start'});}async function initializeTurnstile(){ const response=await fetch('/api/config',{cache:'no-store'});if(!response.ok)throw new Error('TURNSTILE_NOT_CONFIGURED');const config=await response.json();for(let i=0;i<100&&!window.turnstile;i+=1)await new Promise(resolve=>setTimeout(resolve,50));if(!window.turnstile)throw new Error('TURNSTILE_UNAVAILABLE');turnstileWidget=window.turnstile.render(elements.turnstile,{sitekey:config.turnstile_site_key,theme:'light',size:'flexible'}); }

