function renderMywatchTestControls(){const host=document.querySelector('#mywatchTestControls');if(!host)return;if(!mywatchTestEventsEnabled||!memberSession){host.classList.add('hidden');host.replaceChildren();return;}const ui=notificationUiCopy[elements.language.value]||notificationUiCopy.JA;host.classList.remove('hidden');const seed=document.createElement('button');seed.type='button';seed.className='mywatch-test-button';seed.textContent=ui.testSeed;seed.addEventListener('click',()=>seedMywatchTestNotifications());const clear=document.createElement('button');clear.type='button';clear.className='mywatch-test-button';clear.textContent=ui.testClear;clear.addEventListener('click',()=>clearMywatchTestNotifications());host.replaceChildren(seed,clear);}
