async function waitForTurnstileToken(){for(let attempt=0;attempt<100;attempt+=1){const token=window.turnstile?.getResponse(turnstileWidget)||'';if(token)return token;if(attempt===0&&turnstileWidget!==null)window.turnstile?.reset(turnstileWidget);await new Promise(resolve=>setTimeout(resolve,100));}return '';}
// v3.4 fix: Turnstile tokens are single-use server-side. The main search
// form already resets the widget after every submission (see the form's
// finally block), so waitForTurnstileToken's reuse-if-present behavior is
// safe there. HOSHILU AI Chat calls this once per chat turn (potentially
// several times in one dialog session without an intervening main-search
// reset), so reusing whatever token happens to still be cached would send
// an already-consumed token on the 2nd+ turn and fail server-side
// verification ("通信に失敗しました" - reproduced and confirmed via the
// real production chat). Always reset first so every call gets a fresh one.
async function waitForFreshTurnstileToken(){if(turnstileWidget!==null)window.turnstile?.reset(turnstileWidget);for(let attempt=0;attempt<100;attempt+=1){const token=window.turnstile?.getResponse(turnstileWidget)||'';if(token)return token;await new Promise(resolve=>setTimeout(resolve,100));}return '';}
// Exposed for ai-search-ui.mjs (HOSHILU AI Chat), which needs the same
// session_id and Turnstile token as the main search form. Uses a window
// global rather than an ES module import so app.js is never evaluated a
// second time under a different cache-busting query string (which would
// silently double-register the form's submit listener).
window.HoshiluChatAuth={sessionId,requestToken:()=>waitForFreshTurnstileToken()};
function renderCuratedDiscoveryMatch(){const existing=elements.cards.querySelector('.curated-discovery-match');const match=swippittDiscoveryMatch(elements.query.value);if(!match){existing?.remove();return;}if(existing)return;const language=elements.language.value||'JA';const question={JA:'これですか？↓',EN:'Is this it? ↓',ZH:'是这个吗？↓',KO:'이 제품인가요? ↓'}[language]||'これですか？↓';const card=document.createElement('article');card.className='product-card curated-discovery-match';const mediaLink=document.createElement('a');mediaLink.className='curated-discovery-media-link';mediaLink.href=match.url;mediaLink.target='_blank';mediaLink.rel='noopener noreferrer';mediaLink.setAttribute('aria-label',`${match.name} 公式サイト`);const image=document.createElement('img');image.className='product-image curated-discovery-media';image.src=match.imageUrl;image.alt='Swippitt HubとSwippitt Link';image.loading='lazy';image.decoding='async';image.referrerPolicy='no-referrer';mediaLink.append(image);card.append(textElement('span','rank','HOSHILU VERIFIED MATCH'),textElement('strong','curated-match-question',question),mediaLink,textElement('h3','',match.name),textElement('p','',match.description));const link=document.createElement('a');link.className='buy-link';link.href=match.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Swippitt公式サイトで確認';card.append(link);elements.cards.prepend(card);}
const curatedDiscoveryObserver=new MutationObserver(renderCuratedDiscoveryMatch);curatedDiscoveryObserver.observe(elements.cards,{childList:true});
// Extracted from the form's submit handler so the AI chat flow (ai-search-
// ui.mjs) can run the exact same search - real success/failure included -
// instead of faking a click and polling elements.submit.disabled, which
// could not distinguish "results rendered" from "silently did nothing".
// Exposed on window (see the HoshiluChatAuth precedent above) for the same
// reason: app.js must never be evaluated a second time as an ES module.
async function runKnowledgeSearch(){const t=selectedCopy();const currentRoot=String(elements.query.value||'').split(' / ')[0].trim().toLocaleLowerCase();searchAttempt=currentRoot&&currentRoot===searchRoot?Math.min(2,searchAttempt+1):1;searchRoot=currentRoot;elements.status.className='status';elements.status.textContent=t.loading;elements.submit.disabled=true;try{const token=await waitForTurnstileToken();if(!token)throw new Error('TURNSTILE_TOKEN_UNAVAILABLE');const response=await fetch('/api/knowledge',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({query:elements.query.value,consent:elements.consent.checked,session_id:sessionId,language:elements.language.value,search_attempt:searchAttempt,turnstile_token:token,...(window.HoshiluGrowthAttribution||{})})});const payload=await response.json();if(!response.ok||!payload.ok)throw new Error(payload.error||'SEARCH_FAILED');rememberMemberSearch(elements.query.value);renderResults(payload.result,response.headers.get('x-request-id'));elements.status.textContent='';return{ok:true,result:payload.result};}catch(error){rememberMemberSearch(elements.query.value);renderResults(emergencyMarketplaceFallback(elements.query.value));elements.status.className='status';elements.status.textContent='';return{ok:false,error:String(error?.message||error)};}finally{elements.submit.disabled=false;if(turnstileWidget!==null)window.turnstile?.reset(turnstileWidget);}}
window.HoshiluSearch={run:runKnowledgeSearch};
elements.form.addEventListener('submit',event=>{event.preventDefault();runKnowledgeSearch();});
